def choose_move(observation):
    def g(obj, key, default=None):
        try:
            return obj.get(key, default)
        except Exception:
            return default

    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def is_coord(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1])

    def to_coord(v):
        if is_coord(v):
            return (v[0], v[1])
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("row", "col"), ("r", "c"), ("i", "j")):
                if a in v and b in v and is_num(v[a]) and is_num(v[b]):
                    return (v[a], v[b])
        return None

    def extract_position(obs):
        keys = ("position", "pos", "agent_pos", "self_pos", "player_pos", "location", "loc", "coord", "coordinates")
        for k in keys:
            v = g(obs, k)
            c = to_coord(v)
            if c is not None:
                return c
        me = g(obs, "self")
        if isinstance(me, dict):
            for k in keys:
                c = to_coord(g(me, k))
                if c is not None:
                    return c
        return (0, 0)

    def extract_size(obs):
        w = g(obs, "width")
        h = g(obs, "height")
        if is_num(w) and is_num(h):
            return (w, h)
        sh = g(obs, "shape")
        if isinstance(sh, (list, tuple)) and len(sh) >= 2 and is_num(sh[0]) and is_num(sh[1]):
            return (sh[1], sh[0])
        grid = g(obs, "grid")
        if isinstance(grid, (list, tuple)) and grid:
            h = len(grid)
            first = grid[0]
            if isinstance(first, (list, tuple)):
                w = len(first)
                return (w, h)
        return None

    def flatten_points(v):
        pts = []
        if v is None:
            return pts
        if is_coord(v):
            pts.append((v[0], v[1]))
            return pts
        if isinstance(v, dict):
            c = to_coord(v)
            if c is not None:
                pts.append(c)
                return pts
            for vv in v.values():
                pts.extend(flatten_points(vv))
            return pts
        if isinstance(v, (list, tuple)):
            if len(v) == 2 and is_coord(v):
                pts.append((v[0], v[1]))
                return pts
            for item in v:
                pts.extend(flatten_points(item))
        return pts

    def nearest(points, origin):
        best = None
        best_d = None
        ox, oy = origin
        for p in points:
            dx = p[0] - ox
            dy = p[1] - oy
            d = dx * dx + dy * dy
            if best_d is None or d < best_d:
                best_d = d
                best = p
        return best, best_d

    pos = extract_position(observation)
    size = extract_size(observation)
    cx = (size[0] - 1) / 2 if size else pos[0]
    cy = (size[1] - 1) / 2 if size else pos[1]

    mode = g(observation, "mode")
    if mode is None:
        mode = g(observation, "task")
    if mode is None:
        mode = g(observation, "game_mode")
    mode = str(mode).lower() if mode is not None else ""

    resource_keys = (
        "resources", "resource", "food", "foods", "items", "collectibles", "pickups",
        "gold", "treasure", "gems", "goal", "goals", "targets", "objective", "objectives"
    )
    threat_keys = (
        "enemies", "enemy", "opponents", "opponent", "predators", "hazards", "hazard",
        "traps", "trap", "hostiles", "hostile"
    )
    control_keys = (
        "territories", "territory", "cells", "zones", "frontier", "bases", "base",
        "flags", "flag", "points", "capture_points"
    )

    good = []
    bad = []

    for k in resource_keys:
        good.extend(flatten_points(g(observation, k)))
    for k in threat_keys:
        bad.extend(flatten_points(g(observation, k)))
    for k in control_keys:
        good.extend(flatten_points(g(observation, k)))

    # Also inspect common nested containers
    for container_key in ("entities", "objects", "agents", "players"):
        vv = g(observation, container_key)
        if isinstance(vv, (list, tuple)):
            for item in vv:
                if isinstance(item, dict):
                    typ = str(g(item, "type", "")).lower()
                    c = to_coord(item)
                    if c is not None:
                        if any(t in typ for t in ("enemy", "opponent", "hazard", "trap")):
                            bad.append(c)
                        elif any(t in typ for t in ("resource", "food", "goal", "flag", "base", "territory", "zone")):
                            good.append(c)

    # If no explicit mode, infer from available data.
    if "pursuit" in mode or "evasion" in mode:
        pass
    elif "territory" in mode:
        pass
    elif "resource" in mode or "collect" in mode:
        pass

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    target, td = nearest(good, pos) if good else (None, None)
    threat, hd = nearest(bad, pos) if bad else (None, None)

    best_move = (0, 0)
    best_score = None

    for dx, dy in moves:
        nx = pos[0] + dx
        ny = pos[1] + dy
        score = 0.0

        # Stay in bounds when known.
        if size is not None:
            if nx < 0 or ny < 0 or nx >= size[0] or ny >= size[1]:
                score -= 1000.0

        # Attraction to goal/resource/territory.
        if target is not None:
            tx = target[0] - nx
            ty = target[1] - ny
            dist2 = tx * tx + ty * ty
            score += 60.0 / (1.0 + dist2)
            score += 3.0 * (-(abs(tx) + abs(ty)))

        # Repulsion from threats.
        if threat is not None:
            hx = threat[0] - nx
            hy = threat[1] - ny
            dist2h = hx * hx + hy * hy
            score += 40.0 * (dist2h / (1.0 + dist2h))
            score -= 2.0 * (1.0 / (1.0 + dist2h))

        # Centering fallback for territory control / unknown maps.
        if not good:
            cxv = cx - nx
            cyv = cy - ny
            score += 1.5 / (1.0 + cxv * cxv + cyv * cyv)

        # Slight preference for moving rather than waiting when evidence exists.
        if dx == 0 and dy == 0:
            score -= 0.25 if (good or bad) else 0.0

        # If threatened and close, strongly prefer increasing distance.
        if threat is not None and hd is not None and hd <= 25:
            old_dx = threat[0] - pos[0]
            old_dy = threat[1] - pos[1]
            old_d2 = old_dx * old_dx + old_dy * old_dy
            new_d2 = (threat[0] - nx) * (threat[0] - nx) + (threat[1] - ny) * (threat[1] - ny)
            score += 5.0 * (new_d2 - old_d2)

        # Deterministic tie-breaker.
        score += 1e-6 * (dx * 7 + dy * 11)

        if best_score is None or score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [best_move[0], best_move[1]]

